  "forfest.kapten.10.start": "{a} är Överste: den som pratar med {a} utan att säga 'överste' {k1}.",
  "forfest.kapten.10.end": "Översten har gått i pension.",
  "forfest.kapten.11": "{a} är Kapten. Alla {k1} för kaptenens hälsa. Skål!",
  "forfest.kapten.12": "{a} är Kapten och ger alla ett nytt smeknamn för resten av spelet.",
  "forfest.kapten.13": "{a} är Kapten och utser en vicekapten. Vicekaptenen {k1} av ren glädje.",
  "forfest.kapten.14": "{a} är Kapten och byter plats med vem hen vill.",
  "forfest.kapten.15.start": "{a} är Kapten: ingen får skratta när kaptenen pratar. Skrattar du? {K1}.",
  "forfest.kapten.15.end": "Skratta. Kaptenen är klar.",
